(P/'components/ui.tsx').write_text('''import React from 'react';import {Info,ShieldCheck,AlertTriangle,ChevronRight} from 'lucide-react';import type {Quantity} from '../types';import {fmt} from '../api';
export function Badge({children,tone='muted'}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
export function Panel({title,kicker,children,action,className=''}:{title:string;kicker?:string;children:React.ReactNode;action?:React.ReactNode;className?:string}){return <section className={'panel '+className}><div className="panel-head"><div>{kicker&&<small className="eyebrow">{kicker}</small>}<h2>{title}</h2></div>{action}</div>{children}</section>}
export function Q({q,onSource}:{q?:Quantity|null;onSource:(q:any)=>void}){return q?<span className="quantity"><b>{fmt(q.value)}</b> <small>{q.unit}</small><button className="source-button" aria-label={'查看来源 '+q.source_name} title="查看数据来源" onClick={()=>onSource(q)}><Info size={13}/></button></span>:<span className="muted">N/A</span>}
export function Notice({children,tone='amber'}:{children:React.ReactNode;tone?:string}){return <div className={'notice '+tone}><AlertTriangle size={16}/><div>{children}</div></div>}
export function Metric({label,value,sub,tone='cyan'}:{label:string;value:React.ReactNode;sub?:string;tone?:string}){return <div className={'metric '+tone}><small>{label}</small><strong>{value}</strong>{sub&&<span>{sub}</span>}</div>}
export function Empty({title,text}:{title:string;text:string}){return <div className="empty"><ShieldCheck size={32}/><h3>{title}</h3><p>{text}</p></div>}
export function Modal({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){return <div className="modal-backdrop" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button onClick={onClose}>关闭 ×</button></header>{children}</section></div>}
export function NextLabel({children}:{children:React.ReactNode}){return <>{children}<ChevronRight size={16}/></>}
''',encoding='utf-8')
(P/'components/ProcessCanvas.tsx').write_text(r'''import {useEffect,useRef,useState} from 'react';import {ZoomIn,ZoomOut,Pause,Play,Maximize2} from 'lucide-react';
export function ProcessCanvas({id,revision,onSelect}:{id:string;revision:number;onSelect:(v:any)=>void}){
 const ref=useRef<HTMLDivElement>(null);const [markup,setMarkup]=useState('');const [error,setError]=useState('');const [zoom,setZoom]=useState(1);const [paused,setPaused]=useState(()=>matchMedia('(prefers-reduced-motion: reduce)').matches);
 useEffect(()=>{let cancelled=false;fetch('/api/projects/'+id+'/canvas').then(async r=>{if(!r.ok)throw Error((await r.json()).detail);return r.text()}).then(s=>{if(!cancelled)setMarkup(s)}).catch(e=>setError(e.message));return()=>{cancelled=true}},[id,revision]);
 useEffect(()=>{const svg=ref.current?.querySelector('svg');if(!svg)return;const click=(e:Event)=>{const target=(e.target as Element).closest('[data-stream-id],[data-equipment-id]');if(!target)return;svg.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));target.classList.add('selected');onSelect(target.getAttribute('data-stream-id')?{kind:'stream',id:target.getAttribute('data-stream-id')}:{kind:'equipment',id:target.getAttribute('data-equipment-id')})};const key=(e:KeyboardEvent)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();click(e)}};svg.addEventListener('click',click);svg.addEventListener('keydown',key);
 svg.querySelectorAll('path.stream-pipe').forEach(path=>{const hit=path.cloneNode() as SVGPathElement;hit.removeAttribute('id');hit.setAttribute('class','stream-hit');hit.setAttribute('stroke','transparent');hit.setAttribute('stroke-width','22');hit.removeAttribute('marker-end');path.after(hit)});
 svg.querySelectorAll('[data-stream-id],[data-equipment-id]').forEach(el=>{if(!el.querySelector('title')){const t=document.createElementNS('http://www.w3.org/2000/svg','title');t.textContent='点击检查 '+(el.getAttribute('data-stream-id')||el.getAttribute('data-equipment-id'));el.append(t)}});
 return()=>{svg.removeEventListener('click',click);svg.removeEventListener('keydown',key)}},[markup,onSelect]);
 useEffect(()=>{const svg=ref.current?.querySelector('svg');if(svg)paused?svg.pauseAnimations():svg.unpauseAnimations()},[paused,markup]);
 const drag=useRef<{x:number;y:number;sx:number;sy:number}|null>(null);
 return <div className="canvas-shell"><div className="canvas-toolbar"><span>PROCESS CANVAS · DOM / SVG</span><div><button aria-label="缩小" onClick={()=>setZoom(z=>Math.max(.65,z-.15))}><ZoomOut size={16}/></button><span>{Math.round(zoom*100)}%</span><button aria-label="放大" onClick={()=>setZoom(z=>Math.min(3,z+.15))}><ZoomIn size={16}/></button><button aria-label="适合画布" onClick={()=>setZoom(1)}><Maximize2 size={16}/></button><button onClick={()=>setPaused(p=>!p)}>{paused?<Play size={15}/>:<Pause size={15}/>} {paused?'播放':'暂停'}</button></div></div>{error?<div className="notice red">{error}</div>:<div className="canvas-scroll" onPointerDown={e=>{if(!(e.target as Element).closest('[data-stream-id],[data-equipment-id]'))drag.current={x:e.clientX,y:e.clientY,sx:e.currentTarget.scrollLeft,sy:e.currentTarget.scrollTop}}} onPointerMove={e=>{if(drag.current&&e.buttons){e.currentTarget.scrollLeft=drag.current.sx-(e.clientX-drag.current.x);e.currentTarget.scrollTop=drag.current.sy-(e.clientY-drag.current.y)}}} onPointerUp={()=>drag.current=null} onPointerLeave={()=>drag.current=null}><div ref={ref} className="process-svg" style={{width:zoom*100+'%'}} dangerouslySetInnerHTML={{__html:markup}}/></div>}<div className="canvas-foot">点击设备或流股查看工程数据和来源 · 空白处拖动平移 · 动画为原理示意</div></div>
}
''',encoding='utf-8')
(P/'components/Charts.tsx').write_text(r'''import {fmt} from '../api';
export function EnergyChart({rows,onSource}:{rows:any[];onSource:(x:any)=>void}){const max=Math.max(1,...rows.map(r=>Math.abs(r.duty.value)));return <div className="energy-chart">{rows.map((r,i)=><button className="energy-row" key={i} onClick={()=>onSource(r.duty)}><span>{r.id}</span><div><i style={{width:Math.abs(r.duty.value)/max*100+'%',background:r.duty.value<0?'var(--cyan)':'var(--purple)'}}/></div><b>{fmt(r.duty.value)} kW</b></button>)}</div>}
export function ParetoChart({rows}:{rows:any[]}){const points=rows.filter(r=>r.thermal.value!=null&&r.power.value!=null);const xmax=Math.max(1,...points.map(r=>r.thermal.value))*1.15,ymax=Math.max(1,...points.map(r=>r.power.value))*1.2;return <div className="pareto"><svg viewBox="0 0 640 360" role="img" aria-label="参考方案热负荷与电功率比较，非优化前沿"><defs><pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#315061"/></pattern></defs><rect x="60" y="25" width="550" height="280" fill="url(#dots)"/><path d="M60 25 V305 H610" stroke="#38536a" fill="none"/>{[0,.25,.5,.75,1].map(t=><g key={t}><text x={60+t*550} y="326" textAnchor="middle">{fmt(xmax*t,0)}</text><text x="50" y={305-t*280} textAnchor="end">{fmt(ymax*t,0)}</text></g>)}<text x="335" y="352" textAnchor="middle">报告的正热负荷 / kW</text><text transform="translate(15 170) rotate(-90)" textAnchor="middle">报告的电功率 / kW</text>{points.map(r=><g key={r.id} transform={`translate(${60+r.thermal.value/xmax*550} ${305-r.power.value/ymax*280})`}><circle r="7" fill="#a58aff" stroke="#d5caff"/><text x="10" y="-12">{r.id.toUpperCase()}</text><title>{r.title}: {r.thermal.value} kW / {r.power.value} kW</title></g>)}{!points.length&&<text x="335" y="160" textAnchor="middle">尚无同时具备两项目标数据的参考点</text>}</svg><p>REFERENCE COMPARISON · 无优化器，不生成 Pareto 曲线；缺失电功率不视为 0。</p></div>}
''',encoding='utf-8')
